/**
 * Documentation generated by Claude
 * Purpose: Builds and reads the links stored in campsite QR codes, and encodes them as QR patterns.
 * Role / Design Pattern: Utility object with no Android dependencies, so it can be unit tested.
 * Outstanding Issues: None.
 */
package com.example.campsitelottery

import com.google.zxing.BarcodeFormat
import com.google.zxing.EncodeHintType
import com.google.zxing.common.BitMatrix
import com.google.zxing.qrcode.QRCodeWriter
import com.google.zxing.qrcode.decoder.ErrorCorrectionLevel
import java.net.URI

/**
 * Each campsite's QR code holds the link `campsitelottery://campsite/{campsiteId}`.
 *
 * The link is built from the campsite's Firestore ID, which is unique, so every
 * campsite gets its own code and nothing extra needs to be stored.
 */
object CampsiteQrCode {

    const val SCHEME = "campsitelottery"
    const val HOST = "campsite"

    /** Campsite IDs the app accepts from a QR code: Firestore auto IDs and the test data's IDs. */
    private val VALID_ID = Regex("[A-Za-z0-9_-]{1,128}")

    /**
     * Returns the link stored in [campsiteId]'s QR code.
     *
     * @throws IllegalArgumentException if [campsiteId] isn't a valid campsite ID.
     */
    fun linkFor(campsiteId: String): String {
        require(VALID_ID.matches(campsiteId)) { "Not a valid campsite ID: $campsiteId" }
        return "$SCHEME://$HOST/$campsiteId"
    }

    /**
     * Reads the campsite ID out of scanned QR text.
     *
     * @return the campsite ID, or null if the text isn't a campsite link from this app.
     */
    fun campsiteIdFrom(scannedText: String?): String? {
        val text = scannedText?.trim().orEmpty()
        if (text.isEmpty()) return null
        val uri = runCatching { URI(text) }.getOrNull() ?: return null
        if (!SCHEME.equals(uri.scheme, ignoreCase = true)) return null
        if (!HOST.equals(uri.host, ignoreCase = true)) return null
        val id = uri.path.orEmpty().removePrefix("/").removeSuffix("/")
        return id.takeIf { VALID_ID.matches(it) && uri.query == null && uri.fragment == null }
    }

    /**
     * Suggests a file name for a saved QR code image, such as
     * `pine-ridge-retreat-qr-code.png`.
     */
    fun fileNameFor(campsiteName: String): String {
        val slug = campsiteName.lowercase()
            .replace(Regex("[^a-z0-9]+"), "-")
            .trim('-')
            .take(60)
            .trim('-')
            .ifEmpty { "campsite" }
        return "$slug-qr-code.png"
    }

    /**
     * Encodes [text] as a square QR pattern [size] modules wide, with a small
     * quiet border.
     */
    fun encode(text: String, size: Int = 512): BitMatrix =
        QRCodeWriter().encode(
            text,
            BarcodeFormat.QR_CODE,
            size,
            size,
            mapOf(
                EncodeHintType.MARGIN to 1,
                EncodeHintType.ERROR_CORRECTION to ErrorCorrectionLevel.M,
            ),
        )
}
